import { defineComponent } from 'vue';
import { PrizeLeagueManager } from '../../../services/prize-league/prize-league-manager';
import { ITournament } from '../../../services/prize-league/types';
import MenuBar from '../menu-bar/menu-bar.vue';
import { getPrizeLeagueManager, formatDate } from '../prize-league-utils';
import { inversifyContainer } from '../../../inversify/container';

export default defineComponent({
    name: 'TournamentList',
    components: {
        MenuBar
    },
    props: {
        visible: {
            type: Boolean,
            default: true
        }
    },
    computed: {
        prizeLeagueManager(): PrizeLeagueManager {
            return getPrizeLeagueManager();
        },
        tournamentList(): ITournament[] {
            return this.prizeLeagueManager.tournamentList.value;
        },
        activeTournamentEntry(): ITournament | null {
            return this.tournamentList.find(t => t.tournamentStatus === 'Active') ?? null;
        },
        upcomingTournaments(): ITournament[] {
            return this.tournamentList.filter(t => t.tournamentStatus === 'Upcoming');
        },
        defaultTournamentId(): string {
            // Return active tournament if it exists, otherwise first upcoming tournament
            return this.activeTournamentEntry?.tournamentId ?? this.upcomingTournaments[0]?.tournamentId ?? '';
        },
        translations() {
            return inversifyContainer.strings.prizeLeague;
        }
    },
    emits: ['change-panel'],
    methods: {
        onViewClicked(tournamentID: string) {
            // Check if this is an active tournament
            const tournament = this.tournamentList.find(t => t.tournamentId === tournamentID);
            if (tournament && tournament.tournamentStatus === 'Active') {
                this.$emit('change-panel', 'leaderboard', tournamentID);
            } else {
                this.$emit('change-panel', 'prizeList', tournamentID);
            }
        },
        onHistoryClicked() {
            this.prizeLeagueManager.fetchTournamentHistory();
            this.$emit('change-panel', 'history');
        },
        async onOptInClicked(tournamentID: string) {
            const success = await this.prizeLeagueManager.optInToTournament(tournamentID);
            
            if (!success) return;

            const tournament = this.prizeLeagueManager.tournamentList.value.find(t => t.tournamentId === tournamentID);
            if (tournament && tournament.tournamentStatus === 'Active') {
                this.$emit('change-panel', 'leaderboard', tournamentID);
            }
        },
        formatDate(date: Date): string {
            return formatDate(date);
        }
    }
});